import {createLobbyCharacter} from './lobby-character.js';
import {journeyFor} from './gse-routes.js';
import {ROOMS,STORAGE_KEY,validProgress,requiredCompletedCount,requiredRemaining,isRoomUnlocked,canEnterRoom,canEscape,isRoomOrigin,parseRoomMessage,createDoorTracker} from './mission-state.js';
const app=document.getElementById('app');
const lobbyScene='2172808776581645156';
let solved=[];try{solved=validProgress(JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]'));}catch{}
let view='board',active=null,lastCompleted=null,lastLeft=null,roomFrame=null,lobbyFrame=null,tracker=null,loadTimeout,character=null,pendingRoom=null,journey=null,controlCleanup=null,explorerHidden=false;
const lock='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>';
const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 12h16M14 6l6 6-6 6"/></svg>';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(solved));}catch{}}
function roomUrl(id){return 'https://www.thinglink.com/view/scene/'+id+'?lang=en&embed=1';}
function progress(){const required=requiredCompletedCount(solved);return '<div class="progress" aria-label="'+solved.length+' '+(solved.length===1?'point':'points')+'; '+required+' of 4 required missions complete"><span class="progress-count">'+solved.length+' <span>'+(solved.length===1?'point':'points')+'</span></span><div class="progress-lights">'+ROOMS.map(r=>'<i class="'+(solved.includes(r.number)?'lit ':'')+(r.optional?'bonus-light':'')+'" title="Room '+r.number+(r.optional?' (optional bonus)':'')+(solved.includes(r.number)?' complete':' remaining')+'"></i>').join('')+'</div><span class="progress-caption">'+required+' / 4 required'+(solved.includes('357')?' + bonus':'')+'</span></div>';}
function roomCard(r){const done=solved.includes(r.number),locked=!isRoomUnlocked(r.number,solved),remaining=Math.max(0,(r.unlockAfter||0)-solved.length);const label=done?(r.optional?'Bonus cleared':'Cleared'):locked?(remaining===1?'1 more point to unlock':remaining+' points to unlock'):r.optional?'Enter bonus':'Enter room';return '<button class="lobby-room '+(done?'is-cleared ':'')+(locked?'is-locked ':'')+(r.optional?'is-bonus':'')+'" data-room="'+r.number+'" '+(!canEnterRoom(r.number,solved)?'disabled':'')+' aria-label="Room '+r.number+', '+r.floor+(r.optional?', optional bonus':'')+', '+label+'"><span class="lobby-room-top">'+r.floor+(r.optional?' · Optional':'')+(done?'<span class="room-tick" aria-hidden="true">✓</span>':locked?lock:arrow)+'</span><strong>'+r.number+'</strong><span class="room-state">'+label+'</span></button>';}
function header(){return '<header class="topbar"><a class="brand" href="#" aria-label="Return to GSE lobby"><span>HAUNTED</span><strong>GSE</strong></a><div class="header-right">'+progress()+(view==='room'?'<button class="text-button" id="board-button" title="Leave this room unsolved and return to the lobby. You can try it again later.">Return to lobby '+arrow+'</button>':'<span class="exit-status '+(canEscape(solved)?'is-open':'')+'">'+lock+(canEscape(solved)?'Exit unlocked':'Exit locked')+'</span>')+'</div></header>';}
function loading(label){return '<div class="room-loading" role="status"><span class="loading-dot"></span><p>'+label+'</p><button id="reload-scene" class="text-button" hidden>Reload scene</button></div>';}
function watchLoading(){loadTimeout=setTimeout(()=>{const el=document.querySelector('.room-loading');if(el){el.querySelector('p').textContent='The scene is taking a moment to load.';document.getElementById('reload-scene').hidden=false;}},18000);document.getElementById('reload-scene').onclick=render;}
function render(){controlCleanup?.();controlCleanup=null;if(journey)clearTimeout(journey.timeout);journey=null;character?.dispose();character=null;pendingRoom=null;clearTimeout(loadTimeout);roomFrame=null;lobbyFrame=null;tracker=null;app.className='view-'+view;
if(view==='room'){
app.innerHTML=header()+'<main class="room-stage"><div class="room-label"><span>MISSION</span><h1>Room '+active.number+'</h1></div>'+loading('Entering Room '+active.number+'…')+'<iframe id="mission-room" title="Room '+active.number+' puzzle" src="'+roomUrl(active.scene)+'" allow="autoplay"></iframe></main>';
roomFrame=document.getElementById('mission-room');tracker=createDoorTracker(active);watchLoading();document.getElementById('board-button').onclick=leaveRoom;mountRoomExperience();
}else if(view==='finish'){
app.innerHTML='<iframe class="backdrop" title="GSE lobby" tabindex="-1" aria-hidden="true" src="'+roomUrl(lobbyScene)+'"></iframe><div class="shade"></div>'+header()+'<main class="finish content-enter"><div class="eyebrow">ALL REQUIRED MISSIONS COMPLETE</div><div class="escape-mark">'+arrow+'</div><h1>You made<br>it out.</h1><p>The doors swing open. You cleared all four required rooms and escaped Haunted GSE. Congratulations!'+(solved.includes('357')?' You cleared the bonus room, too!':'')+'</p><div class="finished-rooms">'+ROOMS.filter(r=>!r.optional||solved.includes(r.number)).map(r=>'<span>✓ '+r.number+(r.optional?' · bonus':'')+'</span>').join('')+'</div><button class="primary" id="new-attempt">Start a new escape '+arrow+'</button></main>';
document.getElementById('new-attempt').onclick=newAttempt;
}else{
const left=requiredRemaining(solved),allDone=canEscape(solved);
const notice=allDone?'The four required rooms are clear. The main exit is open. Room 357 is an optional bonus.':lastCompleted?'Room '+lastCompleted+' cleared. Choose your next mission.':lastLeft?'Room '+lastLeft+' is still unsolved. Try another room, or return to it later.':'Clear four required rooms to open the exit. Optional Room 357 unlocks after you earn 2 points.';
app.innerHTML=header()+'<main class="lobby-stage"><iframe id="lobby-scene" title="Explore the GSE study-room lobby in 360 degrees" src="'+roomUrl(lobbyScene)+'" allow="autoplay"></iframe>'+'<div id="lobby-character" class="lobby-character" aria-hidden="true"></div><div class="walk-status" hidden><span class="walking-light"></span><span id="walk-label" role="status"></span><button class="text-button" id="cancel-walk">Cancel</button></div>'+loading('Entering the GSE lobby…')+'<section class="lobby-welcome content-enter"><span class="eyebrow">YOUR ESCAPE STARTS HERE</span><h1>Study-room lobby</h1><p id="lobby-notice" role="status">'+notice+'</p><span class="lobby-look">Choose a room to follow its corridor and elevator route. Drag the background to look around.</span></section><section class="lobby-directory" aria-label="Lobby room directory"><div class="directory-heading"><div><span class="eyebrow">ROOM DIRECTORY</span><h2>'+(allDone?(solved.includes('357')?'All rooms complete':'Required rooms complete'):'Choose your next room')+'</h2></div><button class="text-button" id="toggle-directory" aria-expanded="true" aria-controls="directory-options">Hide directory</button></div><div id="directory-options"><div class="lobby-rooms">'+ROOMS.map(roomCard).join('')+'</div><div class="directory-bottom"><span>10 minutes · Follow the presentation timer.</span><div class="lobby-exit"><span>'+(allDone?'Ready to escape':left.length+' required '+(left.length===1?'room':'rooms')+' remaining')+'</span><button id="escape" class="primary '+(allDone?'':'locked')+'" '+(allDone?'':'disabled')+'>'+(allDone?'Leave GSE '+arrow:lock+' Main exit locked')+'</button></div></div></div></section><button class="lobby-reset text-button" id="new-attempt">New attempt</button></main>';
lobbyFrame=document.getElementById('lobby-scene');character=createLobbyCharacter(document.getElementById('lobby-character'),{position:innerWidth<=800?[.48,.50]:[.48,.88]});mountCompanionControls(document.querySelector('.lobby-stage'));addRoomTools(document.querySelector('.lobby-stage'));document.getElementById('cancel-walk').onclick=()=>render();watchLoading();app.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>walkToRoom(b.dataset.room));document.getElementById('escape').onclick=()=>{if(canEscape(solved)){view='finish';lastCompleted=null;render()}};document.getElementById('new-attempt').onclick=newAttempt;
document.getElementById('toggle-directory').onclick=()=>{const button=document.getElementById('toggle-directory'),options=document.getElementById('directory-options');options.hidden=!options.hidden;button.setAttribute('aria-expanded',String(!options.hidden));button.textContent=options.hidden?'Choose a room':'Hide directory';};
}
app.querySelector('.brand').onclick=e=>{e.preventDefault();if(pendingRoom)render();else if(view==='room')leaveRoom();else if(view==='finish'){view='board';render()}};
}
function leaveRoom(){lastLeft=active?.number??null;view='board';active=null;lastCompleted=null;render();}
function journeyPhase(index,step,route){
if(!journey)return;journey.stage=index;document.querySelector('.lobby-stage').dataset.journeyStage=String(index);
const text=index===0?'Heading to the lobby elevator…':index===1?'Taking the elevator from floor 1 to floor '+route.floor+'…':'Following the corridor to Room '+route.number+'…';
document.getElementById('walk-label').textContent=text;const label=document.getElementById('route-map-level');if(label)label.textContent=index===1?'Elevator · 1 → '+route.floor:'Floor '+(index===0?1:route.floor);document.querySelectorAll('[data-journey-step]').forEach(el=>el.classList.toggle('current',Number(el.dataset.journeyStep)===index));
}
function walkToRoom(number){
if(pendingRoom||!canEnterRoom(number,solved))return;if(!character){enterRoom(number);return;}
const room=ROOMS.find(r=>r.number===number),route=journeyFor(number),stage=document.querySelector('.lobby-stage');
pendingRoom=number;app.classList.add('is-travelling');document.querySelector('.walk-status').hidden=false;app.querySelectorAll('[data-room]').forEach(b=>b.disabled=true);
character.visible(true);const frame=document.createElement('iframe');frame.id='journey-room';frame.className='journey-destination';frame.title='Arriving at Room '+number;frame.setAttribute('aria-hidden','true');frame.setAttribute('tabindex','-1');frame.setAttribute('allow','autoplay');frame.src=roomUrl(room.scene);stage.append(frame);
journey={room,frame,ready:false,stage:0,timeout:null};
const veil=document.createElement('div');veil.className='route-veil';stage.append(veil);addRouteMiniMap(stage,route);
const panel=document.createElement('section');panel.className='route-panel';panel.setAttribute('aria-label','Route to Room '+number);panel.innerHTML='<span class="eyebrow">GSE ROUTE PREVIEW · 2×</span><h2>Room '+number+'</h2><p>Floor '+route.floor+' · '+route.area+'</p><ol><li data-journey-step="0">Main lobby → elevator</li><li data-journey-step="1">Elevator → floor '+route.floor+'</li><li data-journey-step="2">Corridor → Room '+number+'</li></ol><span class="route-note">Route based on Penn GSE floor plans.</span><button class="text-button" id="skip-route">Skip journey</button><button class="text-button" id="retry-arrival" hidden>Reload destination room</button>';stage.append(panel);
document.getElementById('retry-arrival').onclick=()=>{if(journey){journey.ready=false;journey.frame.src=roomUrl(journey.room.scene);document.getElementById('retry-arrival').hidden=true;}};
document.getElementById('skip-route').onclick=()=>character?.skip();
character.navigate(number,{phase:journeyPhase,position:p=>{const dot=document.getElementById('route-dot');if(dot){dot.setAttribute('cx',String(p.x*20.5+1240));dot.setAttribute('cy',String(p.z*20.5+865));}},door:()=>{if(!journey)return;journey.stage='at-door';if(journey.ready)finishJourney();else awaitRoom();}});
}
function addRouteMiniMap(stage,route){
const paths=route.steps.filter(s=>s.type==='walk').map(s=>s.points.map(p=>[p.x*20.5+1240,p.z*20.5+865]));const all=paths.flat(),x=Math.min(...all.map(p=>p[0]))-130,y=Math.min(...all.map(p=>p[1]))-130,w=Math.max(...all.map(p=>p[0]))-x+130,h=Math.max(...all.map(p=>p[1]))-y+130,end=paths[1].at(-1);
const mini=document.createElement('div');mini.className='route-mini';mini.innerHTML='<span id="route-map-level">Floor 1</span><svg role="img" aria-label="Simplified route map from the main lobby through the elevator to Room '+route.number+'" viewBox="'+[x,y,w,h].join(' ')+'"><polyline points="'+paths[0].map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#90a295" stroke-width="16" stroke-linecap="round" stroke-linejoin="round"/><polyline points="'+paths[1].map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#e7ba79" stroke-width="16" stroke-linecap="round" stroke-linejoin="round"/><rect x="1212" y="837" width="56" height="56" fill="#263b2c" stroke="#f1d7ac" stroke-width="6"/><circle cx="'+end[0]+'" cy="'+end[1]+'" r="23" fill="#e7ba79"/><circle id="route-dot" cx="'+paths[0][0][0]+'" cy="'+paths[0][0][1]+'" r="23" fill="#fff8e5" stroke="#203c2c" stroke-width="6"/></svg><small>□ Elevator · ● Room '+route.number+'</small>';stage.append(mini);
}
function awaitRoom(){if(!journey)return;document.getElementById('walk-label').textContent='At Room '+journey.room.number+'. Waiting for the room to load…';journey.timeout=setTimeout(()=>{if(journey)document.getElementById('retry-arrival').hidden=false;},12000);}
function finishJourney(){
if(!journey)return;const {room,frame}=journey;if(!canEnterRoom(room.number,solved)){render();return;}clearTimeout(journey.timeout);journey=null;pendingRoom=null;controlCleanup?.();controlCleanup=null;
active=room;lastCompleted=null;lastLeft=null;view='room';roomFrame=frame;lobbyFrame=null;tracker=createDoorTracker(room);app.className='view-room';
const stage=document.querySelector('.lobby-stage'),host=stage.querySelector('#lobby-character');for(const child of [...stage.children])if(child!==frame&&child!==host)child.remove();stage.className='room-stage';delete stage.dataset.journeyStage;
frame.id='mission-room';frame.className='';frame.title='Room '+room.number+' puzzle';frame.removeAttribute('aria-hidden');frame.removeAttribute('tabindex');
stage.insertAdjacentHTML('afterbegin','<div class="room-label"><span>MISSION</span><h1>Room '+room.number+'</h1></div>');app.querySelector('.topbar').outerHTML=header();document.getElementById('board-button').onclick=leaveRoom;app.querySelector('.brand').onclick=e=>{e.preventDefault();leaveRoom()};
character.companion(innerWidth<=800?[.19,.70]:[.15,.86]);mountRoomExperience(true);
}
function addRoomTools(stage){
const tools=document.createElement('div');tools.className='room-tools';tools.innerHTML='<button class="text-button" id="room-controls">How to explore</button><button class="text-button" id="toggle-explorer">'+(explorerHidden?'Show explorer':'Hide explorer')+'</button>';if(stage.classList.contains('lobby-stage')){tools.classList.add('lobby-help-tools');stage.querySelector('.lobby-welcome').append(tools);}else stage.append(tools);
document.getElementById('room-controls').onclick=showRoomControls;document.getElementById('toggle-explorer').onclick=()=>{explorerHidden=!explorerHidden;character?.visible(!explorerHidden);stage.classList.toggle('explorer-hidden',explorerHidden);document.getElementById('toggle-explorer').textContent=explorerHidden?'Show explorer':'Hide explorer';};
}
function mountRoomExperience(keepCharacter=false){
const stage=document.querySelector('.room-stage');if(!keepCharacter){const host=document.createElement('div');host.id='lobby-character';host.className='lobby-character';host.setAttribute('aria-hidden','true');stage.append(host);character=createLobbyCharacter(host,{position:innerWidth<=800?[.19,.70]:[.15,.86]});}
mountCompanionControls(stage);addRoomTools(stage);let seen=false;try{seen=sessionStorage.getItem('gse-room-controls-seen')==='yes';}catch{}if(!seen)showRoomControls();
}
function mountCompanionControls(stage){
if(!character)return;const drag=document.createElement('button');drag.className='explorer-drag';drag.setAttribute('aria-label','Drag explorer to move it');drag.title='Drag the explorer to move it';stage.append(drag);
const controls=document.createElement('div');controls.className='explorer-controls';controls.setAttribute('role','group');controls.setAttribute('aria-label','Move explorer');controls.innerHTML='<span>EXPLORER</span><div class="explorer-pad"><button data-x="0" data-y="-1" aria-label="Move explorer up">↑</button><button data-x="-1" data-y="0" aria-label="Move explorer left">←</button><button data-x="1" data-y="0" aria-label="Move explorer right">→</button><button data-x="0" data-y="1" aria-label="Move explorer down">↓</button></div>';stage.append(controls);
character.listen(p=>{drag.style.left=(p[0]*100)+'%';drag.style.top=(p[1]*100)+'%';});
const char=character,stop=()=>char.direction(0,0);let captured=false;
let offset=[0,0];const point=e=>{const r=stage.getBoundingClientRect();char.target([(e.clientX-offset[0]-r.left)/r.width,(e.clientY-offset[1]-r.top)/r.height]);};
drag.onpointerdown=e=>{e.preventDefault();const r=drag.getBoundingClientRect();offset=[e.clientX-r.left-r.width/2,e.clientY-r.bottom];captured=true;drag.setPointerCapture(e.pointerId);point(e);};drag.onpointermove=e=>{if(captured)point(e)};drag.onpointerup=()=>{captured=false};drag.onpointercancel=()=>{captured=false};
controls.querySelectorAll('button').forEach(button=>{button.onpointerdown=e=>{e.preventDefault();button.focus();button.setPointerCapture(e.pointerId);char.direction(Number(button.dataset.x),Number(button.dataset.y));};button.onpointerup=stop;button.onpointercancel=stop;button.onclick=()=>{char.target([parseFloat(drag.style.left)/100+Number(button.dataset.x)*.045,parseFloat(drag.style.top)/100+Number(button.dataset.y)*.045]);};});
const keys={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]};
const keydown=e=>{if(!controls.contains(document.activeElement)&&document.activeElement!==drag)return;if(keys[e.key]){e.preventDefault();char.target([parseFloat(drag.style.left)/100+keys[e.key][0]*.045,parseFloat(drag.style.top)/100+keys[e.key][1]*.045]);}};const keyup=e=>{if(keys[e.key])stop()};
window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',stop);controls.addEventListener('focusout',stop);
controlCleanup=()=>{char.listen(null);window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup);window.removeEventListener('blur',stop);drag.remove();controls.remove();};
stage.classList.toggle('explorer-hidden',explorerHidden);character.visible(!explorerHidden);
}
function showRoomControls(){
if(document.querySelector('.room-guide'))return;const dialog=document.createElement('dialog');dialog.className='room-guide';dialog.setAttribute('aria-labelledby','guide-title');dialog.innerHTML='<span class="eyebrow">ROOM CONTROLS</span><h2 id="guide-title">Explore the room</h2><ol><li><strong>Look around.</strong> Click and drag the background. On a phone, swipe with one finger.</li><li><strong>Zoom in.</strong> Use your mouse wheel or pinch with two fingers.</li><li><strong>Open clues.</strong> Click the markers. Close the panel when you want to keep exploring.</li><li><strong>Unlock the door.</strong> Open its marker and enter your answer when you are ready.</li><li><strong>Try another room.</strong> Use Return to lobby. An unsolved room stays available.</li></ol><p class="guide-explorer"><strong>Your explorer stays with you.</strong> Drag the character or use the on-screen arrows to move it. Arrow keys and WASD work while its controls are focused.</p><p class="guide-note">Dragging the background turns your view. Furniture and other objects in the photo cannot be picked up.</p><button class="primary" id="close-guide">Got it '+arrow+'</button>';document.body.append(dialog);dialog.showModal();dialog.querySelector('#close-guide').onclick=()=>dialog.close();dialog.onclose=()=>{try{sessionStorage.setItem('gse-room-controls-seen','yes')}catch{}dialog.remove();};
}
function enterRoom(number){const room=ROOMS.find(r=>r.number===number);if(!room||!canEnterRoom(number,solved))return;active=room;lastCompleted=null;lastLeft=null;view='room';render();}
function newAttempt(){const dialog=document.createElement('dialog');dialog.className='reset-dialog';dialog.innerHTML='<h2>Start a new escape?</h2><p>This clears the completed missions on this browser.</p><div><button class="text-button" id="keep-progress">Keep my progress</button><button class="primary" id="reset-progress">Start again</button></div>';document.body.append(dialog);dialog.showModal();dialog.querySelector('#keep-progress').onclick=()=>dialog.close();dialog.querySelector('#reset-progress').onclick=()=>{solved=[];save();active=null;lastCompleted=null;lastLeft=null;view='board';dialog.close();render()};dialog.onclose=()=>dialog.remove();}
function sceneViewed(m,id){return (m.action==='scene.view'&&String(m.sceneId)===id)||(m.action==='TL_STAT'&&m.event==='scene.view'&&String(m.scene?.id)===id);}
window.addEventListener('message',event=>{
if(!isRoomOrigin(event.origin))return;const message=parseRoomMessage(event.data);if(!message)return;
if(journey&&event.source===journey.frame.contentWindow){if(sceneViewed(message,journey.room.scene)){journey.ready=true;if(journey.stage==='at-door')finishJourney();}return;}
if(view==='board'&&lobbyFrame&&event.source===lobbyFrame.contentWindow){if(sceneViewed(message,lobbyScene)){clearTimeout(loadTimeout);document.querySelector('.room-loading')?.remove();}return;}
if(view!=='room'||!active||!roomFrame||event.source!==roomFrame.contentWindow)return;
const bonus=ROOMS.find(r=>r.optional);if(active.number!==bonus.number&&sceneViewed(message,bonus.scene)){if(canEnterRoom(bonus.number,solved))enterRoom(bonus.number);else{leaveRoom();document.getElementById('lobby-notice').textContent=solved.includes(bonus.number)?'The bonus room is already cleared. Choose another mission.':'Room 357 is locked until you earn 2 points. Complete another required room first.';}return;}
if(sceneViewed(message,active.scene)){clearTimeout(loadTimeout);document.querySelector('.room-loading')?.remove();}
if(message.action==='tag.click'||message.action==='TL_POPUP_OPEN')character?.react();
if(active.optional&&!isRoomUnlocked(active.number,solved))return;
if(tracker.observe(message)){const completed=active.number;solved=validProgress([...solved,completed]);save();lastCompleted=completed;lastLeft=null;active=null;view='board';render();}
});
render();
